//! `bsc memory` — the surface that catches what a session learns, as a TYPED GRAPH.
//!
//! A session generates findings, decisions, lessons and parked threads that have no plan item and no
//! code task, and today they evaporate when the terminal closes. This is the append-only, tagged log
//! for exactly those — but the point is the EDGES: a memory carries typed [`Link`]s to the things it
//! relates to (another memory, a graph record id, a symbol anchor like `bsc-disk--sweep.rs#DEFAULT_DAYS`,
//! a plan ref), so memory is a graph you traverse, not a pile you scroll.
//!
//! EVERYTHING IS A NODE. A memory's `kind` says what sort of thing it is, and its links reach any
//! other node — another memory, a code record, a plan ref, a FEATURE, a SESSION. A target may carry an
//! explicit `<type>:` prefix (`feature:auth`, `session:studio-code:director`) so a new node type is
//! added by naming one, never by teaching a parser a new shape.
//!
//! Three facets keep the graph honest:
//! - **`horizon`** separates a memory that is APPLICABLE TO WHAT IS IMPLEMENTED (`now`) from a
//!   discussion of the FUTURE — an idea or a hope (`future`). Traversing "what do we KNOW about this
//!   record" must not be muddled with "what do we DREAM for it".
//! - **`kind`** separates the KINDS of memory that have different provenance and different
//!   lifecycles — a `lesson` (what we got wrong, and the rule), a `highlight` (a discussion that
//!   should persist indefinitely), a `record` note (a code comment explaining why something is the
//!   way it is), an `ambient` capture (what the always-on ear caught), and `note` for anything not
//!   yet classified. It is a FIELD rather than a tag because the reading surfaces, the graph's node
//!   colouring and the session-injection filter all key on it, and a misspelled tag is an invisible
//!   memory.
//! - **`rel`** on each link names the RELATIONSHIP (`about`, `because`, `supersedes`, `contradicts`,
//!   `lesson-of`, `blocks`, `todo-for`, … `related` as the neutral default) — a free string on purpose,
//!   so the vocabulary grows from use rather than being frozen before we have felt which edges we reach for.
//!
//! It is deliberately thin — a shim over the shared `bsc-json-store` (`~/.base-studio-code/memory.db`) —
//! so the interesting parts (the shape, parsing, filtering, ordering) are pure and tested.


use serde::{Deserialize, Deserializer, Serialize};

/// A memory whose `horizon` is unset (a pre-typed-edges record) is applicable-now.
pub const HORIZON_NOW: &str = "now";
/// A forward-looking memory: an idea, a hope, a discussion of the future — NOT yet implemented.
pub const HORIZON_FUTURE: &str = "future";
/// The neutral relationship for a link whose kind was not stated (or a legacy bare-string link).
pub const DEFAULT_REL: &str = "related";

/// What we got wrong, and the rule that came out of it.
pub const KIND_LESSON: &str = "lesson";
/// A discussion or decision that should persist indefinitely — the kind with no other home.
pub const KIND_HIGHLIGHT: &str = "highlight";
/// A comment harvested from code, explaining why a record is the way it is.
pub const KIND_RECORD: &str = "record";
/// What the always-on ear caught — a captured thought, awaiting promotion.
pub const KIND_AMBIENT: &str = "ambient";
/// Not yet classified. The default, so nothing is ever MISLABELLED by omission — an unclassified
/// memory reads as unclassified, which is a work queue, rather than being silently filed as a lesson.
pub const KIND_NOTE: &str = "note";

/// Every kind, in reading order. `note` is last: it is the absence of a classification, not a peer.
pub const KINDS: &[&str] = &[KIND_LESSON, KIND_HIGHLIGHT, KIND_RECORD, KIND_AMBIENT, KIND_NOTE];

/// The node types a link target may name explicitly, as a `<type>:` prefix. Shape inference handles
/// the unprefixed forms that are unambiguous (an all-digit memory id, a `record#SYMBOL` anchor, a
/// `*.rs` record); these exist for the ones that are NOT — a feature slug and a plan ref are the same
/// shape, and a session id is whatever the fleet minted.
///
/// Deliberately a PREFIX and not a second field: `parse_link_specs` splits `rel:ref` on the FIRST
/// colon, so `about:feature:auth` already parses as rel `about` to target `feature:auth` with no
/// grammar change. Adding a node type is naming one here.
pub const NODE_TYPES: &[&str] = &["memory", "record", "plan", "feature", "session", "symbol"];

/// A typed edge from a memory to a target. `target` is any node ref — another memory's id, a graph
/// record id, a symbol anchor, a plan ref, a feature, a session, optionally carrying a `<type>:`
/// prefix — and `rel` names the relationship (see the crate docs).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Link {
    /// What the memory points at. Case-preserving (an id / plan ref is case-significant).
    #[serde(rename = "ref")]
    pub target: String,
    /// The relationship type — a free string; `related` when unstated.
    pub rel: String,
}

impl Link {
    pub fn new(target: impl Into<String>, rel: impl Into<String>) -> Self {
        Link { target: target.into(), rel: rel.into() }
    }
}

/// One captured memory: a finding, a decision, a lesson, or a parked thread.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Memory {
    /// Sortable, unique — nanoseconds since the epoch as a string, so listing by id is listing by time.
    pub id: String,
    /// The thought itself, verbatim.
    pub text: String,
    /// Lowercased tags for retrieval (`rf`, `network`, `lesson`, …).
    pub tags: Vec<String>,
    /// When it was recorded (ms since the epoch).
    pub created_at_ms: i64,
    /// `open` while it still wants doing / still holds; `done` once acted on or folded elsewhere.
    pub status: String,
    /// `now` (applies to what is implemented) or `future` (an idea / hope). Defaults to `now` so a
    /// store written before this facet reads as grounded rather than aspirational.
    #[serde(default = "default_horizon")]
    pub horizon: String,
    /// What SORT of memory this is — see [`KINDS`]. Defaults to `note` so a store written before this
    /// facet reads as UNCLASSIFIED rather than being silently filed under a kind nobody chose.
    #[serde(default = "default_kind")]
    pub kind: String,
    /// Typed edges to related things — the graph. Reads legacy bare-string links as `related`.
    #[serde(default, deserialize_with = "de_links")]
    pub links: Vec<Link>,
}

impl Memory {
    /// Does this memory carry `tag` (case-insensitively)?
    pub fn has_tag(&self, tag: &str) -> bool {
        let t = tag.trim().to_lowercase();
        self.tags.iter().any(|x| x == &t)
    }
    /// Does this memory link to `target` (exact match; targets are case-preserving)?
    pub fn links_to(&self, target: &str) -> bool {
        let t = target.trim();
        self.links.iter().any(|l| l.target == t)
    }
    /// Does this memory carry a link with relationship `rel` (case-insensitively)?
    pub fn has_rel(&self, rel: &str) -> bool {
        let r = rel.trim().to_lowercase();
        self.links.iter().any(|l| l.rel.eq_ignore_ascii_case(&r))
    }
    /// Is this memory of kind `kind` (case-insensitively)?
    pub fn is_kind(&self, kind: &str) -> bool {
        self.kind.eq_ignore_ascii_case(kind.trim())
    }
}

/// The filters a `list`/traversal narrows by. All are AND-ed; `None` means "don't narrow on this".
#[derive(Default)]
pub struct Filter<'a> {
    pub tag: Option<&'a str>,
    pub status: Option<&'a str>,
    /// Keep memories that LINK TO this target (any relationship).
    pub link: Option<&'a str>,
    /// Keep memories that carry a link with this relationship.
    pub rel: Option<&'a str>,
    /// Keep memories on this horizon (`now` / `future`).
    pub horizon: Option<&'a str>,
    /// Keep memories of this kind (`lesson` / `highlight` / `record` / `ambient` / `note`).
    pub kind: Option<&'a str>,
}

/// Accept BOTH the typed object form `{"ref": "...", "rel": "..."}` and the legacy bare string `"..."`
/// (which becomes a `related` link), so a store written before typed edges still reads.
pub(crate) fn de_links<'de, D: Deserializer<'de>>(d: D) -> Result<Vec<Link>, D::Error> {
    #[derive(Deserialize)]
    #[serde(untagged)]
    enum Wire {
        Bare(String),
        Full(Link),
    }
    Ok(Vec::<Wire>::deserialize(d)?
        .into_iter()
        .map(|w| match w {
            Wire::Bare(s) => Link::new(s, DEFAULT_REL),
            Wire::Full(l) => l,
        })
        .collect())
}

pub(crate) fn default_horizon() -> String {
    HORIZON_NOW.to_string()
}

pub(crate) fn default_kind() -> String {
    KIND_NOTE.to_string()
}

/// The `list` view: memories newest-first, narrowed by [`Filter`]. Pure over a slice so the ordering
/// and filtering are tested without a store.
pub fn filter_and_order<'a>(items: &'a [Memory], f: &Filter) -> Vec<&'a Memory> {
    let mut v: Vec<&Memory> = items
        .iter()
        .filter(|i| f.tag.is_none_or(|t| i.has_tag(t)))
        .filter(|i| f.status.is_none_or(|s| i.status.eq_ignore_ascii_case(s)))
        .filter(|i| f.link.is_none_or(|r| i.links_to(r)))
        .filter(|i| f.rel.is_none_or(|r| i.has_rel(r)))
        .filter(|i| f.horizon.is_none_or(|h| i.horizon.eq_ignore_ascii_case(h)))
        .filter(|i| f.kind.is_none_or(|k| i.is_kind(k)))
        .collect();
    // Newest first — the last thought is usually the one you are looking for.
    v.sort_by(|a, b| b.created_at_ms.cmp(&a.created_at_ms).then(b.id.cmp(&a.id)));
    v
}

/// Is `k` a kind this crate knows? An unknown kind is REFUSED at the CLI rather than stored, because
/// a typo'd kind is a memory that never appears under any tab.
pub fn is_kind(k: &str) -> bool {
    KINDS.iter().any(|x| x.eq_ignore_ascii_case(k.trim()))
}

/// Parse a comma-separated value into normalized, de-duplicated, blank-free items. `lowercase` is on
/// for tags (`RF`, ` rf ` and `rf` are one) and off for refs (an id / plan ref keeps its case).
pub(crate) fn parse_csv(s: &str, lowercase: bool) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    for raw in s.split(',') {
        let t = raw.trim();
        let t = if lowercase { t.to_lowercase() } else { t.to_string() };
        if !t.is_empty() && !out.contains(&t) {
            out.push(t);
        }
    }
    out
}

/// Parse a `--link` value into TYPED links. Each comma item is `rel:ref`; an item with no colon is a
/// `related` link to that ref. Case is preserved on the ref; de-duplicated by (rel, ref). So
/// `--link about:bsc-graph--methods.rs,supersedes:old-id` is two edges, and a bare `--link some-id`
/// is one `related` edge.
pub fn parse_link_specs(s: &str) -> Vec<Link> {
    let mut out: Vec<Link> = Vec::new();
    for raw in s.split(',') {
        let item = raw.trim();
        if item.is_empty() {
            continue;
        }
        let link = match item.split_once(':') {
            Some((rel, target)) if !rel.trim().is_empty() && !target.trim().is_empty() => {
                Link::new(target.trim(), rel.trim().to_lowercase())
            }
            // No usable `rel:` prefix — the whole item is the target, related.
            _ => Link::new(item, DEFAULT_REL),
        };
        if !out.iter().any(|l| l.target == link.target && l.rel == link.rel) {
            out.push(link);
        }
    }
    out
}

/// Parse a `--tag a,b,c` value into normalized tags: trimmed, lowercased, de-duplicated, no blanks.
pub fn parse_tags(s: &str) -> Vec<String> {
    parse_csv(s, true)
}

/// The `<type>:` prefix on `target`, when it carries one this crate knows.
pub fn target_type(target: &str) -> Option<&'static str> {
    let t = target.trim();
    NODE_TYPES.iter().copied().find(|ty| {
        t.len() > ty.len() + 1 && t.as_bytes()[ty.len()] == b':' && t[..ty.len()].eq_ignore_ascii_case(ty)
    })
}
